COMMENT ON COLUMN account_balance.pending_debits IS 'Active holds and pending debits';
COMMENT ON COLUMN account_balance.pending_credits IS 'Pending credits not yet available';
COMMENT ON COLUMN account_balance.available_balance IS 'Posted - pending debits + overdraft limit';
COMMENT ON COLUMN account_balance.account_version IS 'Last applied ledger entry version';
COMMENT ON COLUMN account_balance.last_entry_at IS 'Time of the last posting';
COMMENT ON COLUMN account_balance.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN account_balance.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN account_balance.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN account_balance.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN account_balance.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_account_balance_tenant ON account_balance (tenant_id, created_at);
ALTER TABLE account_balance ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON account_balance USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_account_balance_touch BEFORE UPDATE ON account_balance FOR EACH ROW EXECUTE FUNCTION touch_row();

-- hold: A reservation of funds (card authorisation, pending payment, legal block) reducing available balance
CREATE TABLE hold (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  ledger_account_id            uuid NOT NULL REFERENCES ledger_account(id),
  hold_type                    varchar(40) NOT NULL CHECK (hold_type IN ('CARD_AUTHORIZATION', 'PAYMENT', 'MANUAL', 'LEGAL', 'CHEQUE', 'RESERVATION')),
  amount                       numeric(28,8) NOT NULL,
  currency                     char(3) NOT NULL,
  captured_amount              numeric(28,8) NOT NULL DEFAULT 0,
  status                       varchar(40) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'PARTIALLY_CAPTURED', 'CAPTURED', 'RELEASED', 'EXPIRED')),
  source_type                  varchar(64),
  source_id                    uuid,
  idempotency_key              varchar(128) NOT NULL,
  description                  varchar(500),
  expires_at                   timestamptz,
  released_at                  timestamptz,
  metadata                     jsonb,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500),
  CONSTRAINT uq_hold_1 UNIQUE (tenant_id, idempotency_key)
);
COMMENT ON TABLE hold IS 'A reservation of funds (card authorisation, pending payment, legal block) reducing available balance';
COMMENT ON COLUMN hold.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN hold.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN hold.created_at IS 'Creation time';
COMMENT ON COLUMN hold.created_by IS 'Principal that created the row';
COMMENT ON COLUMN hold.updated_at IS 'Last update time';
COMMENT ON COLUMN hold.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN hold.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN hold.ledger_account_id IS 'Account the funds are reserved on';
COMMENT ON COLUMN hold.hold_type IS 'Reason for the hold';
COMMENT ON COLUMN hold.amount IS 'Held amount (can be incremented)';
COMMENT ON COLUMN hold.currency IS 'Currency';
COMMENT ON COLUMN hold.captured_amount IS 'Amount converted into postings';
COMMENT ON COLUMN hold.status IS 'Lifecycle status';
COMMENT ON COLUMN hold.source_type IS 'Business object type, e.g. CARD_AUTHORIZATION';
COMMENT ON COLUMN hold.source_id IS 'Business object id';
COMMENT ON COLUMN hold.idempotency_key IS 'Taken from the Idempotency-Key header';
COMMENT ON COLUMN hold.description IS 'Narrative';
COMMENT ON COLUMN hold.expires_at IS 'Automatic release time';
COMMENT ON COLUMN hold.released_at IS 'Time released or expired';
COMMENT ON COLUMN hold.metadata IS 'Client-defined key/value metadata';
COMMENT ON COLUMN hold.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN hold.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN hold.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN hold.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN hold.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_hold_tenant ON hold (tenant_id, created_at);
CREATE INDEX ix_hold_ledger_account_id ON hold (ledger_account_id);
CREATE INDEX ix_hold_source_id ON hold (source_id);
ALTER TABLE hold ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON hold USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_hold_touch BEFORE UPDATE ON hold FOR EACH ROW EXECUTE FUNCTION touch_row();

-- hold_event: Immutable history of a hold (placed, incremented, captured, released, expired)
CREATE TABLE hold_event (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  hold_id                      uuid NOT NULL REFERENCES hold(id),
  event_type                   varchar(32) NOT NULL,
  amount                       numeric(28,8) NOT NULL,
  journal_entry_id             uuid REFERENCES journal_entry(id),
  reason                       varchar(255),
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
COMMENT ON TABLE hold_event IS 'Immutable history of a hold (placed, incremented, captured, released, expired)';
COMMENT ON COLUMN hold_event.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN hold_event.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN hold_event.created_at IS 'Creation time';
COMMENT ON COLUMN hold_event.created_by IS 'Principal that created the row';
COMMENT ON COLUMN hold_event.hold_id IS 'Hold';
COMMENT ON COLUMN hold_event.event_type IS 'PLACED, INCREMENTED, CAPTURED, PARTIALLY_CAPTURED, RELEASED, EXPIRED';
COMMENT ON COLUMN hold_event.amount IS 'Amount affected by this event';
COMMENT ON COLUMN hold_event.journal_entry_id IS 'Posting created on capture';
COMMENT ON COLUMN hold_event.reason IS 'Reason supplied by the caller';
COMMENT ON COLUMN hold_event.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN hold_event.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN hold_event.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN hold_event.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN hold_event.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_hold_event_tenant ON hold_event (tenant_id, created_at);
CREATE INDEX ix_hold_event_hold_id ON hold_event (hold_id);
CREATE INDEX ix_hold_event_journal_entry_id ON hold_event (journal_entry_id);
ALTER TABLE hold_event ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON hold_event USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_hold_event_append_only BEFORE UPDATE OR DELETE ON hold_event FOR EACH ROW EXECUTE FUNCTION forbid_mutation();

-- balance_snapshot: End-of-day balance per account; used for statements, interest and point-in-time queries
